// One compact digest instead of one API call per message: cheaper, and the model
// can rank the whole inbox against itself rather than judging each mail alone.
const lines = [];
for (const item of $input.all()) {
  const m = item.json;
  const headers = m.payload?.headers || [];
  const get = (n) => (headers.find(h => h.name.toLowerCase() === n) || {}).value || '';
  const body = (m.snippet || '').replace(/\s+/g, ' ').slice(0, 400);
  lines.push([
    `ID: ${m.id}`,
    `FROM: ${get('from')}`,
    `SUBJECT: ${get('subject')}`,
    `SNIPPET: ${body}`
  ].join('\n'));
}
return [{ json: { count: lines.length, digest: lines.join('\n---\n') } }];

