// The model was told to answer with JSON only, but a wrapper still shows up now and
// then — so parse defensively and fail loudly rather than sending an empty message.
const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
let data;
try {
  data = JSON.parse(text.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim());
} catch (e) {
  throw new Error('Claude did not return JSON. First 200 characters: ' + text.slice(0, 200));
}
const urgent = data.urgent || [];
const later = data.later || [];
const lines = [`*Inbox* — ${urgent.length} urgent, ${later.length} later, ${data.ignore_count || 0} ignored`, '', data.summary || ''];
for (const u of urgent) {
  lines.push('', `*${u.from}*`, u.why, '', `_draft:_ ${u.draft}`);
}
if (later.length) {
  lines.push('', '*Later*');
  for (const l of later) lines.push(`• ${l.from} — ${l.why}`);
}
return [{ json: { text: lines.join('\n'), urgent } }];
